import numpy as np
from sklearn.preprocessing import KBinsDiscretizer
for value in [-0.1, -0.2, -0.3, -0.7, -1.1]:
 for count in range(2, 30):
  X = np.array([0.] + [value] * count + [2.])[:, None]
  for bins in range(3, 50):
   edges = np.percentile(X[:, 0], np.linspace(0, 100, bins + 1))
   if np.any(np.diff(edges[1:]) < 0):
    print('repro', value, count, bins)
    print('decreasing edges', np.flatnonzero(np.diff(edges) < 0), np.diff(edges)[np.diff(edges) < 0])
    KBinsDiscretizer(n_bins=bins, encode='ordinal').fit_transform(X)
    raise RuntimeError('Expected transform failure')

